    10	export const schema = {
    11	  text:    { type: "string", default: "Make something people want to watch twice, then cut it in half" },
    12	  stagger: { type: "number", default: 4, min: 1, max: 30, step: 1 },
    13	  color:   { type: "color",  default: "#ffffff" },
    14	  accent:  { type: "color",  default: "#ffd60a" },
    15	};
    16	
    17	export function render(frame, props, ctx) {
    18	  const u = Math.min(ctx.width, ctx.height) / 1080;
    19	  const font = { family: "Montserrat", size: 110 * u, weight: 900 };
    20	  const lines = wrapText(props.text, ctx.width * 0.8, font);
    21	  const space = measureText("a a", font).width - measureText("aa", font).width;
    22	  const lineHeight = font.size * 1.15;
    23	  const firstBaseline = ctx.height / 2 - ((lines.length - 1) * lineHeight) / 2 + font.size * 0.35;
    24	  let body = "";
    25	  let index = 0;
    26	  lines.forEach((line, row) => {
    27	    const words = line.split(" ");
    28	    const widths = words.map((w) => measureText(w, font).width);
    29	    const total = widths.reduce((a, b) => a + b, 0) + space * (words.length - 1);
    30	    let x = (ctx.width - total) / 2;
    31	    const y = firstBaseline + row * lineHeight;
    32	    words.forEach((word, i) => {
    33	      const s = spring({ frame: frame - index * props.stagger, fps: ctx.fps, stiffness: 160, damping: 12 });
    34	      const cx = x + widths[i] / 2;
    35	      const fill = index % 5 === 3 ? props.accent : props.color;
    36	      if (s > 0.001) {
    37	        body += `<g transform="translate(${cx} ${y}) scale(${s}) translate(${-cx} ${-y})">` +
    38	          `<text x="${x}" y="${y}" font-family="Montserrat" font-weight="900" font-size="${font.size}"` +
    39	          ` fill="${fill}">${escapeXml(word)}</text></g>`;
    40	      }
    41	      x += widths[i] + space;
    42	      index++;
    43	    });
    44	  });
    45	  return svg(ctx, body, { background: "#0b0b10" });
    46	}
