531	    27	  const edge = dark ? "#4a4a54" : "#c4c4cc";
532	    28	  const field = dark ? "#1b1b20" : "#ffffff";
533	    29	  const ink = dark ? "#e8e8ee" : "#2a2a31";
534	    30	  const faint = dark ? "#8a8a96" : "#8a8a96";
535	    31	  const scale = Math.max(0.5, Math.min(1, props.scale));
536	    32	  const safeW = ctx.width * 0.9;
537	    33	  const safeH = ctx.height * 0.9;
538	    34	  // The outline (2u, straddling the edge) stays inside title-safe even at scale 1.
539	    35	  const lw = 2 * u;
540	    36	  const w = Math.min(safeW * scale, safeW - 2 * lw);
541	    37	  const h = Math.min(safeH * scale, safeH - 2 * lw);
542	    38	  const x = (ctx.width - w) / 2;
543	    39	  const y = (ctx.height - h) / 2;
544	    40	  const r = 12 * u;
545	    41	  const barH = 64 * u;
546	    42	  const enter = spring({ frame, fps: ctx.fps, stiffness: 120, damping: 17 });
547	    43	  // The geometry never overshoots, so the window never grows past its settled size.
548	    44	  const settle = Math.min(1, enter);
