550	    46	  const grow = 0.96 + 0.04 * settle;
551	    47	  const alpha = Math.max(0, Math.min(1, enter * 1.6)) * out;
552	    48	  const cx = ctx.width / 2;
553	    49	  const cy = ctx.height / 2;
