2	     1	// countdown — a bundled template (spec §11 G-44): a timer counting from
3	     2	// `from` to `to` one step a second (up when `to` is greater), its digits
4	     3	// pulsing on each tick inside a ring that empties or fills, and a flash at
5	     4	// the end.
6	     5	export const meta = {
7	     6	  name: "Countdown",
8	     7	  category: "Data & Time",
9	     8	  description: "A timer counting down or up inside a ring, flashing at the end.",
10	     9	  durationInFrames: 330,
11	    10	};
12	    11	
13	    12	export const schema = {
14	    13	  from:   { type: "number",  default: 10 },
15	    14	  to:     { type: "number",  default: 0 },
16	    15	  format: { type: "enum",    default: "m:ss", options: ["seconds", "m:ss", "h:mm:ss"] },
17	    16	  label:  { type: "string",  default: "Starting in" },
18	    17	  ring:   { type: "boolean", default: true },
19	    18	  accent: { type: "color",   default: "#ff5a36" },
20	    19	};
21	    20	
22	    21	function clock(n, format) {
23	    22	  const sign = n < 0 ? "-" : "";
24	    23	  const s = Math.abs(n);
25	    24	  const two = (v) => String(v).padStart(2, "0");
26	    25	  if (format === "seconds") return sign + s;
27	    26	  if (format === "h:mm:ss") return `${sign}${Math.floor(s / 3600)}:${two(Math.floor(s / 60) % 60)}:${two(s % 60)}`;
28	    27	  return `${sign}${Math.floor(s / 60)}:${two(s % 60)}`;
29	    28	}
30	    29	
31	    30	export function render(frame, props, ctx) {
32	    31	  const u = Math.min(ctx.width, ctx.height) / 1080;
33	    32	  const D = ctx.durationInFrames;
34	    33	  const from = Math.round(props.from);
35	    34	  const to = Math.round(props.to);
36	    35	  const steps = Math.abs(to - from);
37	    36	  const t = Math.max(0, ctx.time);
38	    37	  const ticked = Math.min(steps, Math.floor(t));
39	    38	  const n = to < from ? from - ticked : from + ticked;
40	    39	  const done = t >= steps;
41	    40	  const cx = ctx.width / 2;
42	    41	  const cy = ctx.height / 2;
43	    42	  const R = 300 * u;
44	    43	  const thick = 22 * u;
45	    44	  const enter = spring({ frame, fps: ctx.fps, stiffness: 140, damping: 15 });
46	    45	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
47	    46	  const local = t - Math.floor(t);
48	    47	  const pulse = done && t - steps > 0.3 ? 1 : interpolate(local, [0, 0.3], [1.08, 1], { easing: Easing.outCubic, clamp: true });
49	    48	  // From equal to `to` there is nothing to count: the ring stands at its end state and nothing flashes.
50	    49	  const left = steps === 0 ? 0 : Math.max(0, Math.min(1, 1 - t / steps));
51	    50	  const ringShown = to < from ? left : 1 - left;
52	    51	  const text = clock(n, props.format);
53	    52	  const widest = clock(from, props.format).length >= clock(to, props.format).length
54	    53	    ? clock(from, props.format) : clock(to, props.format);
55	    54	  const digitSize = fitText(widest.replace(/[0-9]/g, "0"), R * 1.45, { family: "IBM Plex Mono", weight: 500 },
56	    55	    { min: 12 * u, max: 190 * u });
57	    56	  const flash = done && steps > 0 ? interpolate(t - steps, [0, 0.6], [0.85, 0], { easing: Easing.outCubic, clamp: true }) : 0;
58	    57	  const labelText = props.label.toUpperCase();
59	    58	  const labelSize = fitText(labelText, R * 1.3, { family: "Montserrat", weight: 800, letterSpacing: 5 * u },
60	    59	    { min: 10 * u, max: 34 * u });
61	    60	  const circumference = 2 * Math.PI * R;
62	    61	  return svg(ctx, `
63	    62	    <g opacity="${out * Math.min(1, enter * 1.4)}"
64	    63	       transform="translate(${cx} ${cy}) scale(${0.85 + 0.15 * enter}) translate(${-cx} ${-cy})">
65	    64	      <circle cx="${cx}" cy="${cy}" r="${R + thick / 2 + 8 * u}" fill="#101014" fill-opacity="0.82"/>
66	    65	      ${flash > 0 ? `<circle cx="${cx}" cy="${cy}" r="${R + thick / 2 + 8 * u}" fill="${props.accent}" fill-opacity="${flash}"/>` : ""}
67	    66	      ${props.ring ? `
68	    67	      <circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="#ffffff" stroke-opacity="0.12" stroke-width="${thick}"/>
