102	    22	function arc(cx, cy, r, a0, a1) {
103	    23	  const at = (a) => {
104	    24	    const t = ((a - 90) * Math.PI) / 180;
105	    25	    return `${cx + r * Math.cos(t)} ${cy + r * Math.sin(t)}`;
106	    26	  };
107	    27	  if (a1 - a0 >= 359.99) {
108	    28	    return `M ${at(a0)} A ${r} ${r} 0 1 1 ${at(a0 + 180)} A ${r} ${r} 0 1 1 ${at(a0 + 359.99)}`;
109	    29	  }
110	    30	  return `M ${at(a0)} A ${r} ${r} 0 ${a1 - a0 > 180 ? 1 : 0} 1 ${at(a1)}`;
111	    31	}
