191	    21	const clamp = (v, lo, hi) => Math.max(lo, Math.min(Math.max(lo, hi), v));
192	    22	
193	    23	export function render(frame, props, ctx) {
194	    24	  const u = Math.min(ctx.width, ctx.height) / 1080;
195	    25	  const D = ctx.durationInFrames;
196	    26	  const W = ctx.width;
197	    27	  const H = ctx.height;
198	    28	  const inset = 30 * u;
199	    29	  const x0 = W * 0.05 + inset;
200	    30	  const y0 = H * 0.05 + inset;
201	    31	  const x1 = W * 0.95 - inset;
202	    32	  const y1 = H * 0.95 - inset;
203	    33	  const showBox = props.shape !== "arrow";
204	    34	  const showArrow = props.shape !== "box";
205	    35	  const bw = showBox ? Math.min(x1 - x0, Math.max(0.02, props.boxWidth) * W) : 0;
206	    36	  const bh = showBox ? Math.min(y1 - y0, Math.max(0.02, props.boxHeight) * H) : 0;
207	    37	  const cx = clamp(props.x * W, x0 + bw / 2, x1 - bw / 2);
208	    38	  const cy = clamp(props.y * H, y0 + bh / 2, y1 - bh / 2);
209	    39	  const stroke = 8 * u;
210	    40	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
211	    41	  const font = { family: "Montserrat", size: 56 * u, weight: 800 };
212	    42	  const labelSize = props.label ? fitText(props.label, x1 - x0, font, { min: 10 * u, max: font.size }) : 0;
213	    43	  const labelW = props.label ? measureText(props.label, { family: "Montserrat", size: labelSize, weight: 800 }).width : 0;
214	    44	
215	    45	  let box = "";
216	    46	  if (showBox) {
217	    47	    const r = Math.min(14 * u, bw / 2, bh / 2);
218	    48	    const bx = cx - bw / 2;
219	    49	    const by = cy - bh / 2;
220	    50	    const d = `M ${bx + r} ${by} H ${bx + bw - r} A ${r} ${r} 0 0 1 ${bx + bw} ${by + r} V ${by + bh - r}
221	    51	      A ${r} ${r} 0 0 1 ${bx + bw - r} ${by + bh} H ${bx + r} A ${r} ${r} 0 0 1 ${bx} ${by + bh - r} V ${by + r}
222	    52	      A ${r} ${r} 0 0 1 ${bx + r} ${by} Z`;
